<?php $page_title='Contact Messages';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$a=$_POST['action'];if($a==='delete')$pdo->prepare("DELETE FROM contact_messages WHERE id=?")->execute([$id]);else $pdo->prepare("UPDATE contact_messages SET is_read=? WHERE id=?")->execute([$a==='read'?1:0,$id]);header('Location: messages.php');exit;}$msgs=$pdo->query("SELECT * FROM contact_messages ORDER BY created_at DESC")->fetchAll();?>
<div class="page-head"><div><h1>Contact Messages</h1><p>Manage all customer enquiries.</p></div></div><div class="panel"><div class="table-wrap"><table><tr><th>ID</th><th>From</th><th>Subject</th><th>Message</th><th>Date</th><th>Read</th><th>Actions</th></tr><?php foreach($msgs as $m):?><tr><td>#<?=$m['id']?></td><td><?=e($m['name'])?><br><?=e($m['email'])?></td><td><?=e($m['subject'])?></td><td><?=e(mb_strimwidth($m['message'],0,90,'…'))?></td><td><?=date('M d, Y H:i',strtotime($m['created_at']))?></td><td><?=$m['is_read']?'Read':'<strong>Unread</strong>'?></td><td><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="<?=$m['is_read']?'unread':'read'?>"><button class="btn light"><?=$m['is_read']?'Mark unread':'Mark read'?></button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="delete"><button class="btn danger" data-confirm="Delete this message?">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
